import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { cp, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const SITE = 'https://www.irumx.app';
const futurePath = '/services/scout-future';
const futureUrl = SITE + futurePath;

async function withFixture(check) {
  const fixture = await mkdtemp(join(tmpdir(), 'irumx-sitemap-'));
  try {
    // CLI 는 import.meta.url 기준으로 dist와 의존성을 찾는다.
    await mkdir(join(fixture, 'scripts'));
    await cp(join(root, 'scripts/verify-build.mjs'), join(fixture, 'scripts/verify-build.mjs'));
    await cp(join(root, 'dist'), join(fixture, 'dist'), { recursive: true });
    await symlink(join(root, 'node_modules'), join(fixture, 'node_modules'), 'dir');
    await check(fixture);
  } finally {
    await rm(fixture, { recursive: true, force: true });
  }
}

function verify(fixture) {
  const result = spawnSync(process.execPath, [join(fixture, 'scripts/verify-build.mjs')], {
    cwd: fixture,
    encoding: 'utf8',
  });
  assert.ifError(result.error);
  assert.equal(result.signal, null);
  return result;
}

function assertPass(result) {
  assert.equal(result.status, 0, result.stderr);
  assert.match(result.stdout, /모두 통과/);
}

function assertSitemapFailure(result, missing) {
  assert.equal(result.status, 1, `사이트맵 오류를 거절해야 함: ${missing}\n${result.stdout}${result.stderr}`);
  const errors = result.stderr.trim().split('\n');
  assert.equal(errors.length, 1, result.stderr);
  assert.match(errors[0], /✗ sitemap:.*없음/);
  assert.ok(errors[0].includes(missing), result.stderr);
}

async function addHtml(fixture, path) {
  const source = await readFile(join(fixture, 'dist/services/yeopjari.html'), 'utf8');
  // canonical, og:url, JSON-LD와 자기 링크만 변경하고 다른 서비스·이미지 URL은 유지한다.
  const html = source.replace(/\/services\/yeopjari(?=["#<])/g, path);
  const target = join(fixture, 'dist', path + '.html');
  await mkdir(dirname(target), { recursive: true });
  await writeFile(target, html);
}

async function changeSitemap(fixture, change) {
  const path = join(fixture, 'dist/sitemap-0.xml');
  await writeFile(path, change(await readFile(path, 'utf8')));
}

const addLoc = (url) => (xml) => xml.replace('</urlset>', `<url><loc>${url}</loc></url></urlset>`);

test('현재 정상 빌드는 통과한다', async () => {
  await withFixture(async (fixture) => assertPass(verify(fixture)));
});

test('고정 목록에 없는 서비스 HTML의 loc 누락을 거절한다', async () => {
  await withFixture(async (fixture) => {
    await addHtml(fixture, futurePath);
    assertSitemapFailure(verify(fixture), futureUrl);
  });
});

test('추가 서비스의 정확한 loc가 있으면 통과한다', async () => {
  await withFixture(async (fixture) => {
    await addHtml(fixture, futurePath);
    await changeSitemap(fixture, addLoc(futureUrl));
    assertPass(verify(fixture));
  });
});

for (const suffix of ['.html', '/']) {
  test(`추가 서비스의 loc에 ${suffix}가 붙으면 누락으로 거절한다`, async () => {
    await withFixture(async (fixture) => {
      await addHtml(fixture, futurePath);
      await changeSitemap(fixture, addLoc(futureUrl + suffix));
      assertSitemapFailure(verify(fixture), futureUrl);
    });
  });
}

test('비서비스 HTML·중첩 HTML·이미지는 loc를 요구하지 않는다', async () => {
  await withFixture(async (fixture) => {
    await addHtml(fixture, '/scout-info');
    await addHtml(fixture, '/services/nested/scout-info');
    await cp(join(fixture, 'dist/og/yeopjari.png'), join(fixture, 'dist/services/scout-image.png'));
    assertPass(verify(fixture));
  });
});

test('기존 필수 주소 /about의 loc 누락도 거절한다', async () => {
  await withFixture(async (fixture) => {
    await changeSitemap(fixture, (xml) => xml.replace(`<loc>${SITE}/about</loc>`, ''));
    assertSitemapFailure(verify(fixture), '/about');
  });
});

test('사이트맵에 404가 포함되면 거절한다', async () => {
  await withFixture(async (fixture) => {
    await changeSitemap(fixture, addLoc(`${SITE}/404`));
    const result = verify(fixture);
    assert.equal(result.status, 1, result.stdout + result.stderr);
    assert.match(result.stderr, /✗ sitemap: 404 포함/);
  });
});
